a<-commandArgs(TRUE);root<-normalizePath(a[1]);for(s in c('Cervilla','D1_Johnson','UC_SCC','MPBC1','MPBC2')){f<-file.path(root,s,'tmp/supplement_plot.rds');if(!file.exists(f))next;before<-file.info(f)$size;z<-readRDS(f);tmp<-paste0(f,'.compact');saveRDS(z,tmp,compress='gzip');stopifnot(file.rename(tmp,f));cat(s,'14_gene_plot_cache_bytes',before,'->',file.info(f)$size,'\n');rm(z);gc()}
